def main():
    import sys
    import threading

    def solve():
        import sys
        import threading

        def dfs(node, parent):
            nonlocal order
            order.append(node)
            for neighbor in adj[node]:
                if neighbor != parent:
                    dfs(neighbor, node)

        def process_test_case():
            n = int(sys.stdin.readline())
            edges = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n - 1)]

            adj = [[] for _ in range(n + 1)]
            for u, v in edges:
                adj[u].append(v)
                adj[v].append(u)

            order = []
            dfs(1, -1)

            relabeling = [0] * (n + 1)
            for i, node in enumerate(order, start=1):
                relabeling[node] = i

            print(" ".join(map(str, relabeling[1:])))

        t = int(sys.stdin.readline())
        for _ in range(t):
            process_test_case()

    threading.Thread(target=solve).start()

if __name__ == "__main__":
    main()
